package com.andye.warmod.icbm.network;import com.andye.warmod.WarMod;import java.util.UUID;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.network.codec.StreamCodec;import net.minecraft.network.protocol.common.custom.CustomPacketPayload;import net.minecraft.resources.Identifier;import net.minecraft.world.phys.Vec3;public record ClientboundIcbmGuidanceUpdatePayload(UUID missileId,Vec3 separationPosition,Vec3 resolvedTarget,int revisedCoastTicks,int guidanceTier,double errorX,double errorZ,long resolutionGameTime)implements CustomPacketPayload{public static final Type<ClientboundIcbmGuidanceUpdatePayload> TYPE=new Type<>(Identifier.fromNamespaceAndPath(WarMod.MOD_ID,"icbm_guidance_update"));public static final StreamCodec<RegistryFriendlyByteBuf,ClientboundIcbmGuidanceUpdatePayload> STREAM_CODEC=StreamCodec.of((b,p)->{b.writeUUID(p.missileId);b.writeDouble(p.separationPosition.x);b.writeDouble(p.separationPosition.y);b.writeDouble(p.separationPosition.z);b.writeDouble(p.resolvedTarget.x);b.writeDouble(p.resolvedTarget.y);b.writeDouble(p.resolvedTarget.z);b.writeVarInt(p.revisedCoastTicks);b.writeVarInt(p.guidanceTier);b.writeDouble(p.errorX);b.writeDouble(p.errorZ);b.writeLong(p.resolutionGameTime);},b->new ClientboundIcbmGuidanceUpdatePayload(b.readUUID(),new Vec3(b.readDouble(),b.readDouble(),b.readDouble()),new Vec3(b.readDouble(),b.readDouble(),b.readDouble()),b.readVarInt(),b.readVarInt(),b.readDouble(),b.readDouble(),b.readLong()));public boolean isWellFormed(){return missileId!=null&&separationPosition!=null&&separationPosition.isFinite()&&resolvedTarget!=null&&resolvedTarget.isFinite()&&revisedCoastTicks>0&&guidanceTier>=0&&guidanceTier<=3;}@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}}